#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Attribute observed TTFT from existing evidence; makes no model/network calls."""
import collections,hashlib,json,pathlib,statistics,sys
from run_codex_e2e import load,dump
from summarize_codex_e2e import events,text_time,complete,table

def main():
 root=pathlib.Path(sys.argv[1]);allrows=load(root/'combined_request_results.json');plan={t['index']:t for t in load(root.parent/'codex-e2e/turn_results.json')};data=[];inputs={}
 def read(path,raw=False):
  b=path.read_bytes();inputs[str(path.relative_to(root))]=hashlib.sha256(b).hexdigest();return b if raw else json.loads(b)
 for r in allrows:
  if r.get('first_client_text_ns') is None:continue
  p=root/r['evidence_directory']/'wire';stem=f"{r['request_ids'][0]:04}"
  cm=read(p/(stem+'.client.request.meta.json'));um=read(p/(stem+'.upstream.request.meta.json'));hm=read(p/(stem+'.upstream.headers.meta.json'));ut=read(p/(stem+'.upstream.timing.json'));ct=read(p/(stem+'.client.timing.json'))
  ue=events(read(p/(stem+'.upstream.response.bin'),True),ut);ce=events(read(p/(stem+'.client.response.bin'),True),ct);resp,_=complete(ue);usage=resp['response']['usage'];first=text_time(ue);firstc=text_time(ce)
  d=dict(batch=r['batch'],case=r['case'],index=r['index'],is_new_thread=plan[r['index']]['resumed_session'] is None,client_ttft_ms=r['client_ttft_ms'],full_action_ttft_ms=r['action_to_first_text_ms'],prepare_ms=(r['action_to_first_text_ms']-r['client_ttft_ms']) if r['action_to_first_text_ms'] is not None else None,codex_outside_proxy_ms=r['client_pre_post_overhead_ms'],veil_pre_ms=(um['started_us']-cm['started_us'])/1000,upstream_headers_ms=(hm['at_us']-um['started_us'])/1000,headers_to_upstream_text_ms=(first-hm['at_us'])/1000,first_restore_gap_ms=(firstc-first)/1000,input_tokens=usage['input_tokens'],cached_tokens=usage['input_tokens_details']['cached_tokens'],reasoning_tokens=usage['output_tokens_details']['reasoning_tokens'],output_tokens=usage['output_tokens'],original_request_bytes=cm['body_bytes'],forwarded_request_bytes=um['body_bytes'],response_model=resp['response']['model'],response_id=resp['response']['id'],event_timeline_ms={})
  d['uncached_tokens']=d['input_tokens']-d['cached_tokens'];d['cache_ratio']=d['cached_tokens']/d['input_tokens'];d['upstream_wait_ms']=d['upstream_headers_ms']+d['headers_to_upstream_text_ms'];d['veil_observed_local_ms']=d['veil_pre_ms']+d['first_restore_gap_ms'];d['upstream_share_of_submit_ttft']=d['upstream_wait_ms']/d['client_ttft_ms']
  for v,at in ue:
   if v['type'] in ('response.created','response.in_progress','response.completed') or (v['type']=='response.output_text.delta' and v.get('delta')):
    d['event_timeline_ms'].setdefault(v['type'],(at-um['started_us'])/1000)
  stages=[d[k] for k in ('codex_outside_proxy_ms','veil_pre_ms','upstream_headers_ms','headers_to_upstream_text_ms','first_restore_gap_ms')]
  assert abs(sum(stages)-d['client_ttft_ms'])<1e-6
  assert all(x>=-1e-6 for x in stages)
  data.append(d)
 med=lambda key:statistics.median(x[key] for x in data if x[key] is not None)
 summary=dict(observations=len(data),zero_reasoning_observations=sum(x['reasoning_tokens']==0 for x in data),median_submit_ttft_ms=med('client_ttft_ms'),median_upstream_share=med('upstream_share_of_submit_ttft'),median_local_veil_ms=med('veil_observed_local_ms'),max_local_veil_ms=max(x['veil_observed_local_ms'] for x in data),median_upstream_headers_ms=med('upstream_headers_ms'),median_headers_to_text_ms=med('headers_to_upstream_text_ms'),median_first_restore_gap_ms=med('first_restore_gap_ms'),new_thread_codex_outside_ms=statistics.median(x['codex_outside_proxy_ms'] for x in data if x['is_new_thread']),followup_codex_outside_ms=statistics.median(x['codex_outside_proxy_ms'] for x in data if not x['is_new_thread']))
 inputs['combined_request_results.json']=hashlib.sha256((root/'combined_request_results.json').read_bytes()).hexdigest();inputs['../codex-e2e/turn_results.json']=hashlib.sha256((root.parent/'codex-e2e/turn_results.json').read_bytes()).hexdigest()
 dump(root/'latency_breakdown.json',dict(summary=summary,observations=data));dump(root/'latency_analysis_inputs.json',dict(source_sha256=inputs,analysis_script_sha256=hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest()))
 examples=[next(x for x in data if x['batch']==b and x['case']==c) for b,c in [('recovery2','context_30000_load'),('recovery2','context_30000_recall'),('recovery','continuous_recall_A'),('recovery','formatted_chat_recall_A'),('recovery2','context_5000_recall')]]
 lines=['# 客户端首文本延迟原因分析','', '本分析只重算已归档数据，没有新增模型调用。34 次收到文本的请求包含重试/重建会话，不能当成独立生产抽样；首次容量失败无 TTFT，仍保留在原报告。', '', '## 结论','', '秒级耗时主要落在转发之后、等待上游首文本的阶段。Veil 本地观测到的前处理与首次还原转发仅为数十毫秒；新建 Codex 会话另有约 0.89 秒的代理外开销。极端长尾已经发生在上游响应流中，现有数据无法再把它严格拆成服务端排队、推理调度/预填充或网络/SSE 缓冲。', '', '## 逐请求时间分解','', '所有分段按各自单调时钟计算历时后相加，不直接相减不同进程的原始时间戳。完整客户端 TTFT = 消息准备/建会话 + Codex 代理外前后合计 + Veil 前处理 + 发出请求至上游响应头 + 响应头至上游首文本 + 首次还原转发间隔。表中秒数四舍五入；原始毫秒值见 latency_breakdown.json。','']
 lines.append(table(['场景','完整客户端 TTFT 秒','Codex 准备及代理外开销 ms','Veil 前处理+首次还原 ms','发出请求至上游首文本 秒'],[[x['case'],f"{x['full_action_ttft_ms']/1000:.3f}",f"{(x['prepare_ms'] or 0)+x['codex_outside_proxy_ms']:.3f}",f"{x['veil_observed_local_ms']:.3f}",f"{x['upstream_wait_ms']/1000:.3f}"] for x in examples]))
 lines+=['','## 29 秒与 24 秒长尾发生在哪里','']
 for b,c in [('recovery2','context_5000_recall'),('recovery','formatted_chat_recall_A')]:
  x=next(x for x in data if x['batch']==b and x['case']==c);t=x['event_timeline_ms']
  lines += [f"- {c}：完整客户端 {x['full_action_ttft_ms']/1000:.3f} 秒。转发后 {x['upstream_headers_ms']/1000:.3f} 秒收到响应头，{t['response.in_progress']/1000:.3f} 秒收到 response.in_progress；首文本直到 {t['response.output_text.delta']/1000:.3f} 秒才到。响应头到首文本占 {x['headers_to_upstream_text_ms']/1000:.3f} 秒；输入 {x['input_tokens']:,} token，缓存命中 {x['cache_ratio']*100:.2f}%，reasoning token 为 {x['reasoning_tokens']}。"]
 lines += ['', '两条长尾都在约一秒内收到上游响应头和 in_progress 事件，说明连接当时已经建立，不能把剩下二十多秒都归为新建 TCP/TLS。之后没有收到文本这一点是直接观测；其内部究竟是后端排队、模型执行还是流式数据被网络/上游缓冲，现有记录无法严格区分。', '', '另有一次明确的 serverOverloaded，说明测试期间服务容量出现过压力，因而上游排队/调度是值得优先验证的解释。但这一错误不足以证明其他成功慢请求的每一秒都是排队。', '', '## 已能排除或降低优先级的解释','',f"- 本地隐私处理：前处理最小 {min(x['veil_pre_ms'] for x in data):.3f} ms、最大 {max(x['veil_pre_ms'] for x in data):.3f} ms；首文本还原间隔中位数 {summary['median_first_restore_gap_ms']:.4f} ms。它们含观察器/日志和本机跳转，不能当成未插桩 Veil 净开销，但仍不足以解释秒级长尾。此前 SQLite 并发退化不应直接套用到本次串行、独立测试数据库的 TTFT。", '- 长上下文必然最慢：30,000 字符加载只有约 3.68 秒，5,000 字符回忆却约 29.18 秒；长度与实际 token 数会影响处理成本，但这批数据没有单调关系，无法解释长尾幅度。', f"- medium 思考过多：34 次有文本请求中 {summary['zero_reasoning_observations']} 次的 reasoning_tokens 为 0；24.46 秒的请求也是 0，29.18 秒的请求只有 18。当前证据不支持把全部延迟归于长链思考。官方文档说明 effort 会影响速度/推理 token 使用，但本轮没有 low/medium 对照，无法给出调整收益：[OpenAI 推理模型文档](https://developers.openai.com/api/docs/guides/reasoning)。", '- 缓存没命中：29.18 秒请求只有 147 个未缓存输入 token，24.46 秒请求缓存命中约 98.45%；缓存命中不能消除上游调度、网络和生成等待。', '', '## Codex 客户端和固定提示负担','',f"- 新会话的代理外开销中位数 {summary['new_thread_codex_outside_ms']:.3f} ms；后续轮 {summary['followup_codex_outside_ms']:.3f} ms。这个差值由客户端 TTFT 减代理入口至首文本的历时得到，包含发送前与解码/通知后的合计，尚不能精确归因于 shell 准备、鉴权、调度或客户端解码。", '- 首轮建会话另有约 1.74–1.85 秒。启动至 initialize 本身约 0.17 秒；首次模型目录访问约 1.65–1.90 秒，是可见的冷启动组成部分。不同访问可能重叠，不将这些数字无条件叠加。普通新会话建会话约 60 ms，后续轮无需重复新建会话。', '- 即使提示只要求回复 E2E_OK，实际输入也有 13,043 token、约 65 KB 请求体：Codex 的系统说明、工具定义和环境上下文构成固定底座。慢的 5,000 字符回忆实际有 17,427 输入 token；30,000 字符加载有 37,544。文档长度不是模型实际输入长度。', '- 占位符也会扩张正文：30,000 字符加载请求从 116,574 字节增至 127,807 字节（增加约 9.64%）。这可能带来额外 token 和预填充成本；但本轮没有原文/化名的配对模型对照，不能量化其 TTFT 净增量。', '- 上述固定底座解释了这不是一条几十 token 的裸模型请求，但控制请求本身缓存已命中 9,856 token，不能将其全部视为未缓存预填充成本。', '', '## 优化与下一步验证顺序','', '1. 先做同一输入、同一模型和 effort 的交替直连/Veil 配对对照，并在不同时段重复。当前没有匹配的直连基线，不能把两次不同运行的 TTFT 相减当成 Veil 净增量。', '2. 保留响应头、首个 SSE 控制事件和首文本三个时间点，并增加连接复用、DNS/TCP/TLS 计时与服务端请求追踪。优先区分后端调度与网络/流式缓冲；现有 response_id 和原始流可用于定位。', '3. 复用 Codex 会话/进程，减少反复初始化；进一步测出新会话约 0.89 秒代理外开销的具体调用。', '4. 对纯回显/提取任务建立轻量提示对照，明确 Codex 默认工具/说明的固定成本；再按相同数据做 effort 对照，检查速度和正确性，不能预设降低 effort 必然解决长尾。', '5. 继续优化 Veil 的扫描与 SQLite，但按当前分解预算排优先级：30,000 字符加载的本地观察开销约 82.6 ms，即使其他阶段不变而将这段降至零，总耗时仍约 3.60 秒；29 秒请求的本地观察开销只有约 30.4 ms。', '', '本轮未执行新的对照实验，以上“下一步”是验证方向而非已证实的优化收益。所有分段可由 latency_analysis_inputs.json 中哈希对应的原始文件复算。']
 (root/'LATENCY_ANALYSIS.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
